const r = $input.first().json || {};
if (r.ok === true) return [{ json: { ok: true, ja_agendado: r.ja_agendado === true, quando: String(r.quando || '') } }];
if (r.motivo === 'sem_orcamento_aberto') return [{ json: { ok: false, orientacao: 'Só dá para agendar depois de montar o orçamento. Não avise o cliente.' } }];
return [{ json: { ok: false, orientacao: 'Não foi possível agendar agora. Siga a conversa e não avise o cliente.' } }];
